import json, re, os
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
base = os.path.basename(d)
sessions_file = os.path.normpath(os.path.join(d, '..', '..', 'sessions', base + '.jsonl'))
with open(sessions_file) as f:
    content = f.read().replace('\\\\n', '\n')

# Parse all grids from the session log
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n((?:\d+\s+\d+\s+\d+\n?){1,30})', content):
    k = m.group(1)
    h, w = int(m.group(2)), int(m.group(3))
    raw = m.group(3)
    rows = []
    for line in raw.split('\n'):
        line = line.strip()
        if line:
            row = [int(x) for x in line.split()]
            if row:
                rows.append(row)
    if rows:
        G[k] = rows[:h]
print(f"Loaded {len(G)} grids")
for k in sorted(G.keys()):
    print(f"\n{k}:")
    for row in G[k]:
        print("  ", row)

# Build and output the action JSON
action = {"action": "request_demos"}
print(json.dumps(action))

